  // F44 WS-4b: редактор исправления и предупреждения F-219/223/226/240/384 (содержание прежнее).
  'reparatur.titel': 'Исправленная версия для {id}',
  'reparatur.hinweis': 'Предзаполнено из текущей версии: status установлен в OFFEN, поля прерванного или неудачного шага сброшены, курсор на первом шаге без lauf_id, если он был null. Всё это — предложение: текст ниже можно редактировать, и он отправляется ровно в таком виде.',
  'reparatur.warnungenTitel': 'Проверь перед отправкой',
  'reparatur.keineWarnungen': 'Для этого черновика предупреждений нет.',
  'reparatur.begruendung': 'Обоснование изменения плана (нужно, только если черновик снимает обязательное согласование ZWINGEND)',
  'reparatur.entwurf': 'Новая версия (WORKFLOW_V0)',
  'reparatur.einreichen': 'Отправить',
  'reparatur.verwerfen': 'Отбросить черновик',
  'reparatur.nichtVorbereitbar': 'Исправленную версию нельзя подготовить: {grund}',
  'reparatur.keinJson': 'Черновик — не корректный JSON ({meldung}) — ничего не отправлено.',
  'reparatur.angenommen': 'Новая версия «{id}» принята (версия {version}).',
  'reparatur.warnung.f223': 'F-223: Для {ids} согласование выдано, но шаг ещё не выполнялся. При отправке сервер отбрасывает это поле — шаг затем снова останавливается и требует нового согласования.',
  'reparatur.warnung.f219': 'F-219: lauf_id у {paare} сбрасывается. Следующий шаг тогда стартует без vorgaengerLaufId — ссылка происхождения на предыдущий запуск отсутствует. Не ошибка, но решение.',
  'reparatur.warnung.f226': 'F-226: Этот черновик снимает обязательное согласование для {ids} (ZWINGEND отпадает). Сервер требует для этого обоснование и фиксирует его как решение.',
  'reparatur.warnung.f240Grund': 'F-240: Причина остановки («{grund}») при отправке нормализуется в null и после этого не видна ни в одном представлении. Если её нужно сохранить, скопируй заранее — само решение об остановке остаётся как артефакт.',
  'reparatur.warnung.f240Grenze': 'F-240: Черновик содержит grenzen.max_schritte {grenze}, а {gelaufen} шаг(ов) уже несут lauf_id. Автомат поэтому сразу снова остановится («лимит достигнут») — лимит нужно поднять, иначе исправление не подействует.',
  'reparatur.warnung.f384': 'F-384: Шаг реализации «{schritt}» в состоянии ERFOLGREICH и сохраняет свой lauf_id «{lauf}» — исправление НЕ перезапускает его автоматически. Решение о приёмке этой сборки остаётся действительным и после отправки этой версии, пока шаг не будет вручную сброшен в status:«OFFEN», lauf_id:null — иначе автомат остановится с KLAERUNG_ERFORDERLICH без пересборки.',

