  'abnahme.kanal.nichtErfasst': "не учтено",
  'abnahme.kanal.auswertung': "Оценка",
  'abnahme.kanal.wasTun': "Что делать:",
  'abnahme.kanal.klasse.echt.titel': "Настоящий отказ",
  'abnahme.kanal.klasse.echt.text': "Как минимум одно отклонение прошло не через вопрос тебе (статический запрет, вопросов в запуске не было или отклонение сверх лимита протокола) — оно считается как отказ без канала.",
  'abnahme.kanal.klasse.echt.wasTun': "Как при любом отказе: просмотри отклонённые команды, затем подтверди или измени задачу.",
  'abnahme.kanal.klasse.automatisch.titel': "Канал отклонил автоматически",
  'abnahme.kanal.klasse.automatisch.text': "Как минимум одно отклонение пришло не от тебя, а от самого канала — либо по постоянному правилу (например, граница путей), либо потому что вопрос к тебе остался без ответа до истечения срока. По подсчёту нельзя однозначно определить причину.",
  'abnahme.kanal.klasse.automatisch.wasTun': "Посмотри в разделе «Без ответа» (в блоке «Канал вопросов в этом запуске», а также в деталях запуска): при «Отклонено автоматически» проверь пути и инструменты задания; при «Срок истёк» повтори запуск и ответь вовремя. Если подсчёт не читается, поможет сырой поток запуска.",
  'abnahme.kanal.ursache.regel.text': "Как минимум одно отклонение пришло не от тебя: канал сам отклонил его по постоянному правилу, не спрашивая тебя (например, путь вне рабочей папки, неразрешённый инструмент, команда с управляющими символами).",
  'abnahme.kanal.ursache.regel.wasTun': "Ты ничего не упустил — правило срабатывает намеренно. Проверь, не требует ли задание чего-то вне рабочей папки или с неразрешённым инструментом; если это нужно, измени задание, иначе оставь отклонение как есть.",
  'abnahme.kanal.ursache.frist.text': "Как минимум один вопрос к тебе остался без ответа до истечения срока ожидания — тогда канал его отклонил.",
  'abnahme.kanal.ursache.frist.wasTun': "Проверь, был ли вопрос виден вовремя; повтори запуск и ответь в срок.",
  'abnahme.kanal.ursache.laufEnde.text': "Как минимум один вопрос к тебе был ещё открыт, когда запуск закончился, — канал отклонил его в конце запуска.",
  'abnahme.kanal.ursache.laufEnde.wasTun': "Проверь, почему запуск закончился раньше (ограничение времени, отмена); повтори запуск и ответь на вопрос, пока он идёт.",
  'abnahme.kanal.ursache.protokollgrenze.text': "Запуск отправил больше запросов, чем вмещает журнал (не более {grenze} записей), — все следующие канал отклонил, не спрашивая.",
  'abnahme.kanal.ursache.protokollgrenze.wasTun': "Проверь, почему модель отправила так много запросов (детали запуска, сырой поток); раздели задание на меньшие части и повтори запуск.",
  'abnahme.kanal.klasse.nichtBestaetigt.titel': "Твоё отклонение не подтверждено",
  'abnahme.kanal.klasse.nichtBestaetigt.text': "Как минимум одно отклонение оценка не смогла подтвердить как твоё (например, не совпадают текст отклонения, инструмент или ввод).",
  'abnahme.kanal.klasse.nichtBestaetigt.wasTun': "Проверь сырой поток запуска (CLI мог изменить формат) и повтори запуск; если не пройдёт — сообщи о находке.",
  'abnahme.kanal.klasse.protokoll.titel': "Протокол вопросов непригоден",
  'abnahme.kanal.klasse.protokoll.text': "Протокол канала был недействителен, относился к другому запуску или расходился с состоянием в памяти — ни одно твоё отклонение не засчитано.",
  'abnahme.kanal.klasse.protokoll.wasTun': "Проверь контрольное состояние запуска и повтори запуск.",
  'abnahme.kanal.klasse.nichtGeprueft.titel': "Не проверено — подозрение на обход",
  'abnahme.kanal.klasse.nichtGeprueft.text': "Из-за подозрения на обход отклонения не сверялись с каналом.",
  'abnahme.kanal.klasse.nichtGeprueft.wasTun': "Ответь на подозрение на обход в запуске.",
  'abnahme.kanal.klasse.unbekannt.titel': "Неизвестная причина",
  'abnahme.kanal.klasse.unbekannt.text': "Оценка называет причину, которую этот интерфейс не знает.",
  'abnahme.kanal.klasse.unbekannt.wasTun': "Проверь детали запуска и сырой поток.",
  'abnahme.kanal.abweichung.titel': "Протокол вопросов не подтверждён",
  'abnahme.kanal.abweichung.text': "Файл протокола не совпал с состоянием канала в памяти — подделка, ошибка записи или канал не был открыт для этого запуска. Твои отклонения в этом запуске не засчитаны. Причина:",
  'abnahme.kanal.abweichung.wasTun': "Проверь контрольное состояние запуска (кто записал файл?), затем повтори запуск.",
